-- Informatiker (Informatiker/in EFZ): Bildungsplan-Fragenkatalog (16 × 30 Fragen).
-- Idempotent, additiv und ohne Datenverlust:
--   * course_key-CHECK-Constraints werden auf
--     abu/automechaniker/fage/informatiker/kv/schreiner/strassenbau erweitert.
--   * Module werden nach (course_key, title) gesucht oder angelegt.
--   * Lektionen werden nach (module_id, title) gesucht oder angelegt;
--     position/pass_score werden gesetzt.
--   * Fragen werden positionsbasiert UPSERTet: vorhandene (lesson_id,
--     position) werden aktualisiert (question.id bleibt erhalten, FKs zu
--     question_xp_awards / battle_answers bleiben intakt). Fehlende
--     Positionen werden eingefügt. Positionen > 30 werden entfernt.
--   * Profile, lesson_progress, lesson_attempts werden nicht angetastet.

begin;

-- ============================================================
-- 1) course_key-CHECK-Constraints erweitern
-- ============================================================
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'profiles_active_course_key_ck') then
    alter table public.profiles drop constraint profiles_active_course_key_ck;
  end if;
  alter table public.profiles
    add constraint profiles_active_course_key_ck check (active_course_key in ('abu', 'automechaniker', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if exists (select 1 from pg_constraint where conname = 'modules_course_key_ck') then
    alter table public.modules drop constraint modules_course_key_ck;
  end if;
  alter table public.modules
    add constraint modules_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if to_regclass('public.battle_matches') is not null then
    if exists (select 1 from pg_constraint where conname = 'battle_matches_course_key_ck') then
      alter table public.battle_matches drop constraint battle_matches_course_key_ck;
    end if;
    alter table public.battle_matches
      add constraint battle_matches_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
  end if;
end$$;

-- ============================================================
-- 2) INFORMATIKER: 1 Modul, 16 Lektionen je 30 Fragen
-- ============================================================
do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin
  select id into v_module_id from public.modules where course_key = 'informatiker' and title = 'Informatiker/in EFZ – Bildungsplan' limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Informatiker/in EFZ – Bildungsplan', 'Bildungsplan Informatiker/in EFZ nach BiVo 2021 (ICT-Berufsbildung Schweiz/SBFI). 16 Lektionen entlang der gemeinsamen Handlungskompetenzbereiche HKB a–c und der Fachrichtungen Applikationsentwicklung sowie Plattformentwicklung mit Fokus auf ICT-Projekte, Daten/Datenbanken, Security, Support, Software-Engineering, Tests, Deployment, Netzwerk-, Server- und Cloud-Infrastruktur.', 'informatiker', 100)
    returning id into v_module_id;
  else
    update public.modules set description = 'Bildungsplan Informatiker/in EFZ nach BiVo 2021 (ICT-Berufsbildung Schweiz/SBFI). 16 Lektionen entlang der gemeinsamen Handlungskompetenzbereiche HKB a–c und der Fachrichtungen Applikationsentwicklung sowie Plattformentwicklung mit Fokus auf ICT-Projekte, Daten/Datenbanken, Security, Support, Software-Engineering, Tests, Deployment, Netzwerk-, Server- und Cloud-Infrastruktur.', position = 100 where id = v_module_id;
  end if;

  -- Lektion L01: L01 – ICT-Projekte: Stakeholder, Bedürfnisse und Ziele
  select id into v_lesson_id from public.lessons where module_id = v_module_id and title = 'L01 – ICT-Projekte: Stakeholder, Bedürfnisse und Ziele' limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'L01 – ICT-Projekte: Stakeholder, Bedürfnisse und Ziele', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage beschreibt das Thema Stakeholderanalyse im Beruf Informatiker/in EFZ am besten?', option_a = 'betroffene Personen, Rollen und Interessen systematisch erfassen', option_b = 'nur die technische Lösung betrachten im laufenden Tagesgeschäft', option_c = 'alle Wünsche ungeprüft umsetzen im konkreten Auftrag', option_d = 'Stakeholder erst nach Projektabschluss informieren', correct_option = 'A', explanation = 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema Stakeholderanalyse im Beruf Informatiker/in EFZ am besten?', 'betroffene Personen, Rollen und Interessen systematisch erfassen', 'nur die technische Lösung betrachten im laufenden Tagesgeschäft', 'alle Wünsche ungeprüft umsetzen im konkreten Auftrag', 'Stakeholder erst nach Projektabschluss informieren', 'A', 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.', 1); end if;
  update public.questions set prompt = 'Worauf muss man beim Thema Stakeholderanalyse in der Praxis besonders achten?', option_a = 'nur die technische Lösung betrachten nach gängiger Praxis', option_b = 'betroffene Personen, Rollen und Interessen systematisch erfassen', option_c = 'alle Wünsche ungeprüft umsetzen im üblichen Berufsalltag', option_d = 'Stakeholder erst nach Projektabschluss informieren', correct_option = 'B', explanation = 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.' where lesson_id = v_lesson_id and position = 2;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Worauf muss man beim Thema Stakeholderanalyse in der Praxis besonders achten?', 'nur die technische Lösung betrachten nach gängiger Praxis', 'betroffene Personen, Rollen und Interessen systematisch erfassen', 'alle Wünsche ungeprüft umsetzen im üblichen Berufsalltag', 'Stakeholder erst nach Projektabschluss informieren', 'B', 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.', 2); end if;
  update public.questions set prompt = 'Welche Aussage zum Thema Stakeholderanalyse ist fachlich korrekt?', option_a = 'nur die technische Lösung betrachten im Produktionsalltag', option_b = 'alle Wünsche ungeprüft umsetzen im Werkstattumfeld', option_c = 'betroffene Personen, Rollen und Interessen systematisch erfassen', option_d = 'Stakeholder erst nach Projektabschluss informieren', correct_option = 'C', explanation = 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.' where lesson_id = v_lesson_id and position = 3;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage zum Thema Stakeholderanalyse ist fachlich korrekt?', 'nur die technische Lösung betrachten im Produktionsalltag', 'alle Wünsche ungeprüft umsetzen im Werkstattumfeld', 'betroffene Personen, Rollen und Interessen systematisch erfassen', 'Stakeholder erst nach Projektabschluss informieren', 'C', 'Stakeholderanalyse schafft die Grundlage für passende ICT-Lösungen.', 3); end if;
